style.css:
@-moz-document domain("userstyles.org") {
/* Background */
    body {
        background-color: #0a0f29 !important; /* Deep Dark Blue */
        color: #cfd8dc !important; /* Light Grayish-Blue Text */
    }

    /* Header & Navigation */
    #header, .navbar, .nav, .menu {
        background-color: #102040 !important; /* Dark Navy */
        color: #ffffff !important;
    }

    /* Sidebar & Panels */
    .sidebar, .panel, .widget, .box {
        background-color: #162b50 !important; /* Dark Blue */
        color: #cfd8dc !important;
    }

    /* Buttons */
    .button, .btn, .submit-button {
        background-color: #1e3a75 !important; /* Rich Blue */
        color: #ffffff !important;
        border-color: #294a94 !important;
    }

    /* Hover Effects */
    .button:hover, .btn:hover, .submit-button:hover {
        background-color: #294a94 !important; /* Lighter Blue */
    }

    /* Text Fields & Inputs */
    input, textarea, select {
        background-color: #1a2a4f !important;
        color: #ffffff !important;
        border-color: #294a94 !important;
    }

    /* Links */
    a {
        color: #5fa8ff !important; /* Bright Blue */
    }

    /* Borders */
    .sidebar, .panel, .widget, .box, .btn {
        border-color: #294a94 !important;
    }

    /* Disable Text Selection */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
